double calcPi(int N) {
    int cnt = 0;    // Counter for coprime pairs
    // Loop through all pairs (a, b) where 1 &lt;= a, b &lt;= N
    for (int a = 1; a &lt;= N; a++) {
        for (int b = 1; b &lt;= N; b++) {
            // Check if a and b are coprime
            if (mygcd(a, b) == 1) {
                cnt += 1;  // Increment counter if coprime
