where
    T: Copy + PartialOrd + Sub&lt;Output = T&gt; + From&lt;u8&gt;,
{
    if x &gt;= y {
        let d = x - y;
        (d, d)
    } else {
        let d = y - x;
        (d, d)
    }
}

